    source_valid & ~transducer_generating & transducer_last_1;
  wire        _transducer_cond_WIRE_3 =
    source_valid & ~transducer_generating & ~transducer_last_1;
  wire [3:0]  transducer_cond =
    {_transducer_cond_WIRE_3,
     _transducer_cond_WIRE_2,
     _transducer_cond_WIRE_1,
     _transducer_cond_WIRE_0};
